#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    long long k;
    cin >> k;
    long long count = 0;
    for (int mask = 1; mask < (1 << n); mask++) {
        long long total = 0;
        for (int i = 0; i < n; i++) if (mask >> i & 1) total += a[i];
        if (total == k) count++;
    }
    cout << count << "\n";
    return 0;
}

