#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    long long best = 0, mask = 0;
    for (int bit = 29; bit >= 0; bit--) {
        mask |= 1LL << bit;
        unordered_set<long long> prefixes;
        for (long long x : a) prefixes.insert(x & mask);
        long long candidate = best | (1LL << bit);
        for (long long p : prefixes) if (prefixes.count(p ^ candidate)) { best = candidate; break; }
    }
    cout << best << "\n";
    return 0;
}

